INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 5, 'theory', 'Квиз: процессы и лимиты');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 5, 0, 'Обычный пользователь выполняет в баше ulimit -n 4096 без флагов -S и -H. Что произойдёт?', '["Изменится только мягкое значение, жёсткое останется прежним", "Изменятся и мягкое, и жёсткое значения; поднять жёсткое обратно без прав администратора не получится", "Команда завершится ошибкой: лимиты меняет только root", "Изменится системный лимит для всех пользователей"]', 1, 'Без флагов встроенная команда меняет оба значения. Обычный пользователь может только понижать жёсткое, обратно его не поднять. Чтобы поменять одно мягкое, нужен флаг -S. Лимит действует лишь в этой оболочке и у её потомков.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 5, 1, 'Администратор прописал nginx nofile 65536 в /etc/security/limits.conf, но служба nginx, запущенная systemd, всё равно работает с 1024. Почему?', '["Файл limits.conf читается только при перезагрузке сервера", "Значение 65536 больше fs.file-max", "Мягкое значение нельзя задавать в limits.conf", "Служба не проходит через PAM-сессию входа, поэтому лимиты задаёт юнит: LimitNOFILE="]', 3, 'limits.conf применяет модуль pam_limits при открытии сессии входа. Служба, запущенная systemd, через неё не проходит. Её лимиты задают LimitNOFILE= в юните (или drop-in) и DefaultLimitNOFILE= в system.conf.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 5, 2, 'Что означает oom_score_adj равный -1000 у процесса?', '["OOM killer никогда не выберет этот процесс жертвой", "Процесс убивают первым, потому что он важнее всех", "Процесс получает максимальный приоритет процессора", "Процесс может занимать память без ограничений, но ядро его замедляет"]', 0, 'Значение -1000 исключает процесс из выбора жертвы. +1000 делает его первым кандидатом. На приоритет процессора oom_score_adj не влияет, это отдельная настройка nice.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 5, 3, 'Обычный пользователь запускает renice -n -5 -p на своём процессе с nice 0. Чем это закончится по умолчанию?', '["Успешно: свой процесс можно менять как угодно", "Процесс получит nice 5 вместо -5", "Будет отказано по правам: понижать nice без привилегий или подходящего RLIMIT_NICE нельзя", "Ядро молча проигнорирует команду и ничего не напишет"]', 2, 'Повышать значение nice (понижать приоритет) может каждый владелец. Понижать нужны привилегия CAP_SYS_NICE или RLIMIT_NICE, по умолчанию он равен нулю и не позволяет этого.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 5, 4, 'Что произойдёт при vm.overcommit_memory=2, когда сумма выделенной памяти доходит до CommitLimit?', '["Ядро запустит OOM killer и убьёт самый большой процесс", "Ядро выделит память из подкачки без ограничений", "Система перезагрузится", "Новые выделения памяти завершатся отказом, процессы не убиваются"]', 3, 'В строгом режиме потолок — подкачка плюс доля оперативной памяти. Превышение приводит к ошибке при выделении (malloc или mmap вернёт отказ), а не к убийству процесса позже.');
